package com.passage.reader;

import android.app.Activity;
import android.content.ContentValues;
import android.content.Intent;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import android.net.Uri;
import android.provider.OpenableColumns;
import android.security.keystore.KeyGenParameterSpec;
import android.security.keystore.KeyProperties;
import android.util.Base64;
import androidx.activity.result.ActivityResult;
import com.getcapacitor.JSObject;
import com.getcapacitor.JSArray;
import com.getcapacitor.Plugin;
import com.getcapacitor.PluginCall;
import com.getcapacitor.PluginMethod;
import com.getcapacitor.annotation.CapacitorPlugin;
import com.getcapacitor.annotation.ActivityCallback;
import org.json.JSONArray;
import org.json.JSONObject;
import org.json.JSONTokener;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import javax.crypto.*;
import javax.crypto.spec.GCMParameterSpec;

@CapacitorPlugin(name="PassageNative")
public class PassageNative extends Plugin {
    private final Set<String> tables = new HashSet<>(Arrays.asList("documents","blocks","reading_positions","notes","highlights","translation_cache","terminology","settings","usage_requests","ai_cache","conversations"));
    private final ExecutorService storagePool = Executors.newSingleThreadExecutor();
    private final ExecutorService networkPool = Executors.newFixedThreadPool(2);
    private final ConcurrentHashMap<String,HttpURLConnection> connections = new ConcurrentHashMap<>();
    private SQLiteDatabase db;
    private File papers;
    @Override public void load() {
        papers = new File(getContext().getFilesDir(),"papers"); papers.mkdirs();
        db = getContext().openOrCreateDatabase("passage.sqlite",0,null);
        if (db.getVersion() > 2) throw new IllegalStateException("Database requires a newer Passage version");
        db.beginTransaction();
        try { for(String table:tables) { db.execSQL("CREATE TABLE IF NOT EXISTS "+table+" (id TEXT PRIMARY KEY, document_id TEXT, data TEXT NOT NULL)"); db.execSQL("CREATE INDEX IF NOT EXISTS idx_"+table+"_document ON "+table+"(document_id)"); } db.setVersion(2); db.setTransactionSuccessful(); }
        finally { db.endTransaction(); }
    }
    private Object get(String table,String id) throws Exception { try(Cursor cursor=db.rawQuery("SELECT data FROM "+table+" WHERE id=?",new String[]{id})) { return cursor.moveToFirst()?new JSONTokener(cursor.getString(0)).nextValue():JSONObject.NULL; } }
    private JSONArray list(String table,String documentId) throws Exception { JSONArray rows=new JSONArray(); String sql="SELECT data FROM "+table+(documentId==null?"":" WHERE document_id=?"); try(Cursor c=db.rawQuery(sql,documentId==null?null:new String[]{documentId})){while(c.moveToNext())rows.put(new JSONTokener(c.getString(0)).nextValue());} return rows; }
    private void put(String table,String id,Object data,String documentId) { ContentValues values=new ContentValues();values.put("id",id);values.put("document_id",documentId);values.put("data",data==null?"null":data.toString());db.insertWithOnConflict(table,null,values,SQLiteDatabase.CONFLICT_REPLACE); }
    private JSONObject settings() throws Exception { Object value=get("settings","app");if(!(value instanceof JSONObject))return null;JSONObject settings=(JSONObject)value;JSONArray providers=settings.getJSONArray("providers");for(int i=0;i<providers.length();i++){JSONObject p=providers.getJSONObject(i);p.put("keySet",getContext().getSharedPreferences("credentials",0).contains(p.getString("id")));}return settings; }
    @PluginMethod public void storage(PluginCall call) { storagePool.execute(()->{try { String table=call.getString("table");if(!tables.contains(table))throw new Exception("不支持的数据表。");String op=call.getString("op"),id=call.getString("id"),documentId=call.getString("documentId");Object value=JSONObject.NULL;
        if("get".equals(op))value="settings".equals(table)&&"app".equals(id)?settings():get(table,id);
        else if("list".equals(op))value=list(table,documentId);
        else if("put".equals(op)){if("settings".equals(table))throw new Exception("设置必须通过凭据服务保存。");put(table,id,call.getData().opt("data"),documentId);}
        else if("remove".equals(op)){if("settings".equals(table)||"usage_requests".equals(table))throw new Exception("不支持删除此记录。");db.beginTransaction();try{db.delete(table,"id=?",new String[]{id});if("documents".equals(table)){for(String name:tables)if(!name.equals("documents")&&!name.equals("settings")&&!name.equals("usage_requests"))db.delete(name,"document_id=?",new String[]{id});if(id.matches("[a-f0-9]{64}"))new File(papers,id+".pdf").delete();}db.setTransactionSuccessful();}finally{db.endTransaction();}}
        else throw new Exception("未知操作。");JSObject result=new JSObject();result.put("value",value==null?JSONObject.NULL:value);call.resolve(result);
    }catch(Exception error){call.reject("本地数据操作失败："+error.getMessage());}}); }
    private SecretKey key() throws Exception { KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);String alias="PassageCredentials";if(!store.containsAlias(alias)){KeyGenerator generator=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");generator.init(new KeyGenParameterSpec.Builder(alias,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());generator.generateKey();}return(SecretKey)store.getKey(alias,null); }
    private String encrypt(String plain) throws Exception { Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());return Base64.encodeToString(cipher.getIV(),Base64.NO_WRAP)+":"+Base64.encodeToString(cipher.doFinal(plain.getBytes(StandardCharsets.UTF_8)),Base64.NO_WRAP); }
    private String secret(String providerId) throws Exception { String stored=getContext().getSharedPreferences("credentials",0).getString(providerId,null);if(stored==null)return"";String[] parts=stored.split(":");Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(parts[0],Base64.NO_WRAP)));return new String(cipher.doFinal(Base64.decode(parts[1],Base64.NO_WRAP)),StandardCharsets.UTF_8); }
    @PluginMethod public void saveSettings(PluginCall call) { storagePool.execute(()->{try { JSONObject settings=call.getObject("settings");JSONObject keys=call.getObject("keys");JSONArray providers=settings.getJSONArray("providers");Set<String> ids=new HashSet<>();for(int i=0;i<providers.length();i++){JSONObject p=providers.getJSONObject(i);ids.add(p.getString("id"));p.remove("keySet");for(String field:new String[]{"inputPrice","outputPrice","cachedPrice"})if(p.has(field)&&p.getDouble(field)<0)throw new Exception("价格必须为非负数字。");}android.content.SharedPreferences.Editor editor=getContext().getSharedPreferences("credentials",0).edit();Iterator<String> iterator=keys.keys();while(iterator.hasNext()){String id=iterator.next();if(!ids.contains(id))throw new Exception("未知服务商。");String plain=keys.getString(id);if(plain.isEmpty())editor.remove(id);else editor.putString(id,encrypt(plain));}if(!editor.commit())throw new Exception("无法保存加密凭据。");put("settings","app",settings,null);call.resolve();}catch(Exception e){call.reject("保存失败："+e.getMessage());}}); }
    @PluginMethod public void importPdf(PluginCall call) { Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.setType("application/pdf");intent.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(call,intent,"pickedPdf"); }
    @ActivityCallback private void pickedPdf(PluginCall call,ActivityResult result) { if(call==null)return;if(result.getResultCode()!=Activity.RESULT_OK||result.getData()==null){JSObject value=new JSObject();value.put("value",JSONObject.NULL);call.resolve(value);return;}Uri uri=result.getData().getData();storagePool.execute(()->{try{String name="论文.pdf";try(Cursor cursor=getContext().getContentResolver().query(uri,null,null,null,null)){if(cursor!=null&&cursor.moveToFirst()){int index=cursor.getColumnIndex(OpenableColumns.DISPLAY_NAME);if(index>=0)name=cursor.getString(index);}}byte[] bytes;try(InputStream input=getContext().getContentResolver().openInputStream(uri)){bytes=readLimited(input,64*1024*1024);}if(!new String(bytes,0,Math.min(bytes.length,1024),StandardCharsets.ISO_8859_1).contains("%PDF-"))throw new Exception("不是有效的 PDF。");byte[] digest=MessageDigest.getInstance("SHA-256").digest(bytes);StringBuilder hash=new StringBuilder();for(byte b:digest)hash.append(String.format("%02x",b&255));String id=hash.toString();Object existing=get("documents",id);JSONObject paper;if(existing instanceof JSONObject)paper=(JSONObject)existing;else{try(FileOutputStream output=new FileOutputStream(new File(papers,id+".pdf"))){output.write(bytes);}paper=new JSONObject().put("id",id).put("name",name.replaceAll("(?i)\\.pdf$","")).put("pages",0).put("addedAt",System.currentTimeMillis()).put("openedAt",System.currentTimeMillis());put("documents",id,paper,null);}JSObject value=new JSObject();value.put("value",paper);call.resolve(value);}catch(Exception e){call.reject("导入失败："+e.getMessage());}}); }
    private byte[] readLimited(InputStream input,int limit) throws Exception { ByteArrayOutputStream output=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int count;while((count=input.read(buffer))!=-1){if(output.size()+count>limit)throw new Exception("文件超过移动端 64 MB 限制。");output.write(buffer,0,count);}return output.toByteArray(); }
    @PluginMethod public void readPdf(PluginCall call) { storagePool.execute(()->{try{String id=call.getString("id");if(id==null||!id.matches("[a-f0-9]{64}")||!(get("documents",id) instanceof JSONObject))throw new Exception("论文不存在。");byte[] bytes;try(InputStream input=new FileInputStream(new File(papers,id+".pdf"))){bytes=readLimited(input,64*1024*1024);}JSObject result=new JSObject();result.put("base64",Base64.encodeToString(bytes,Base64.NO_WRAP));call.resolve(result);}catch(Exception e){call.reject("读取失败："+e.getMessage());}}); }
    @PluginMethod public void startFetch(PluginCall call) { networkPool.execute(()->{String id=call.getString("id");HttpURLConnection connection=null;try{String providerId=call.getString("providerId");JSONObject settings=settings();if(settings==null)throw new Exception("请保存服务商设置。");JSONObject provider=null;JSONArray providers=settings.getJSONArray("providers");for(int i=0;i<providers.length();i++)if(providerId.equals(providers.getJSONObject(i).getString("id")))provider=providers.getJSONObject(i);if(provider==null)throw new Exception("未知服务商。");URL url=new URL(call.getString("url")),base=new URL(provider.getString("baseUrl"));boolean localhost=Arrays.asList("localhost","127.0.0.1","::1","[::1]").contains(url.getHost());if(!url.getProtocol().equals("https")&&!(url.getProtocol().equals("http")&&localhost))throw new Exception("远程服务必须使用 HTTPS。");if(!url.getProtocol().equals(base.getProtocol())||!url.getHost().equals(base.getHost())||url.getPort()!=base.getPort()||!url.getPath().startsWith(base.getPath().replaceAll("/$","")+"/"))throw new Exception("拒绝将密钥发送到配置以外的地址。");if(url.getUserInfo()!=null)throw new Exception("URL 不应包含凭据。");connection=(HttpURLConnection)url.openConnection();connection.setInstanceFollowRedirects(false);connection.setRequestMethod("POST");connection.setConnectTimeout(20000);connection.setReadTimeout(90000);connection.setDoOutput(true);connection.setRequestProperty("Content-Type","application/json");String key=secret(providerId);if(providerId.equals("anthropic")){connection.setRequestProperty("x-api-key",key);connection.setRequestProperty("anthropic-version","2023-06-01");}else if(providerId.equals("gemini"))connection.setRequestProperty("x-goog-api-key",key);else if(!key.isEmpty())connection.setRequestProperty("Authorization","Bearer "+key);connections.put(id,connection);try(OutputStream output=connection.getOutputStream()){output.write(call.getString("body").getBytes(StandardCharsets.UTF_8));}int status=connection.getResponseCode();JSObject header=new JSObject();header.put("id",id);header.put("type","headers");header.put("status",status);header.put("contentType",connection.getContentType());notifyListeners("network",header);InputStream input=status>=400?connection.getErrorStream():connection.getInputStream();if(input!=null)try(Reader reader=new InputStreamReader(input,StandardCharsets.UTF_8)){char[] buffer=new char[2048];int count;while((count=reader.read(buffer))!=-1){JSObject chunk=new JSObject();chunk.put("id",id);chunk.put("type","chunk");chunk.put("text",new String(buffer,0,count));notifyListeners("network",chunk);}}JSObject end=new JSObject();end.put("id",id);end.put("type","end");notifyListeners("network",end);call.resolve();}catch(Exception e){JSObject error=new JSObject();error.put("id",id);error.put("type","error");error.put("error","无法连接服务，请检查网络与配置。");notifyListeners("network",error);call.reject("AI 网络请求失败。");}finally{connections.remove(id);if(connection!=null)connection.disconnect();}}); }
    @PluginMethod public void cancel(PluginCall call) { HttpURLConnection connection=connections.remove(call.getString("id"));if(connection!=null)connection.disconnect();call.resolve(); }
    @PluginMethod public void exportData(PluginCall call) { Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("application/json");intent.putExtra(Intent.EXTRA_TITLE,"Passage-backup.json");startActivityForResult(call,intent,"exportPicked"); }
    @ActivityCallback private void exportPicked(PluginCall call,ActivityResult result) { if(call==null)return;if(result.getResultCode()!=Activity.RESULT_OK){JSObject value=new JSObject();value.put("path",JSONObject.NULL);call.resolve(value);return;}storagePool.execute(()->{try{JSONObject backup=new JSONObject().put("version",1).put("exportedAt",System.currentTimeMillis());for(String table:tables)if(!table.equals("settings"))backup.put(table,list(table,null));JSONObject pdfs=new JSONObject();JSONArray documents=list("documents",null);for(int i=0;i<documents.length();i++){String id=documents.getJSONObject(i).getString("id");try(InputStream input=new FileInputStream(new File(papers,id+".pdf"))){pdfs.put(id,Base64.encodeToString(readLimited(input,64*1024*1024),Base64.NO_WRAP));}}backup.put("pdfs",pdfs);backup.put("settings",settings());Uri uri=result.getData().getData();try(OutputStream output=getContext().getContentResolver().openOutputStream(uri)){output.write(backup.toString().getBytes(StandardCharsets.UTF_8));}JSObject value=new JSObject();value.put("path",uri.toString());call.resolve(value);}catch(Exception e){call.reject("导出失败，请检查存储权限。");}}); }
    @Override protected void handleOnPause() { notifyListeners("appPause",new JSObject()); super.handleOnPause(); }
    @Override protected void handleOnDestroy() { for(HttpURLConnection connection:connections.values())connection.disconnect();storagePool.shutdown();networkPool.shutdown();super.handleOnDestroy(); }
}
